-- ========================================================================
-- BEGIN 90_create_table_grade.sql
-- ========================================================================

CREATE TABLE grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    assessment_id UUID NOT NULL UNIQUE
        REFERENCES assessment(id) ON DELETE CASCADE,
    cfs_score INTEGER NOT NULL DEFAULT 1
        CHECK (cfs_score >= 1 AND cfs_score <= 9),
    cfs_category VARCHAR(30) NOT NULL DEFAULT ''
        CHECK (cfs_category IN ('very-fit', 'well', 'managing-well', 'vulnerable', 'mildly-frail', 'moderately-frail', 'severely-frail', 'very-severely-frail', 'terminally-ill', '')),
    functional_domain_score INTEGER
        CHECK (functional_domain_score IS NULL OR functional_domain_score >= 0),
    cognitive_domain_score INTEGER
        CHECK (cognitive_domain_score IS NULL OR cognitive_domain_score >= 0),
    mobility_domain_score INTEGER
        CHECK (mobility_domain_score IS NULL OR mobility_domain_score >= 0),
    nutrition_domain_score INTEGER
        CHECK (nutrition_domain_score IS NULL OR nutrition_domain_score >= 0),
    polypharmacy_domain_score INTEGER
        CHECK (polypharmacy_domain_score IS NULL OR polypharmacy_domain_score >= 0),
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_grade_updated_at
    BEFORE UPDATE ON grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grade IS
    'Computed Clinical Frailty Scale result. CFS 1 = Very fit, 4 = Vulnerable, 7 = Severely frail, 9 = Terminally ill. One-to-one child of assessment.';
COMMENT ON COLUMN grade.cfs_score IS
    'Clinical Frailty Scale score (1-9).';
COMMENT ON COLUMN grade.cfs_category IS
    'CFS category: very-fit, well, managing-well, vulnerable, mildly-frail, moderately-frail, severely-frail, very-severely-frail, terminally-ill, or empty string.';
COMMENT ON COLUMN grade.functional_domain_score IS
    'Sub-score for the functional assessment domain, NULL if not yet scored.';
COMMENT ON COLUMN grade.cognitive_domain_score IS
    'Sub-score for the cognitive screening domain, NULL if not yet scored.';
COMMENT ON COLUMN grade.mobility_domain_score IS
    'Sub-score for the mobility and falls domain, NULL if not yet scored.';
COMMENT ON COLUMN grade.nutrition_domain_score IS
    'Sub-score for the nutrition domain, NULL if not yet scored.';
COMMENT ON COLUMN grade.polypharmacy_domain_score IS
    'Sub-score for the polypharmacy review domain, NULL if not yet scored.';
COMMENT ON COLUMN grade.graded_at IS
    'Timestamp when the grading was computed.';

COMMENT ON COLUMN grade.assessment_id IS
    'Foreign key to the assessment table.';
COMMENT ON COLUMN grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grade.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN grade.updated_at IS
    'Timestamp when this row was updated.';
COMMENT ON COLUMN grade.deleted_at IS
    'Timestamp when this row was deleted.';

-- ========================================================================
-- END 90_create_table_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 91_create_table_grading_fired_rule.sql
-- ========================================================================

CREATE TABLE grading_fired_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    grade_id UUID NOT NULL
        REFERENCES grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(20) NOT NULL,
    category VARCHAR(100) NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '',
    cfs_contribution INTEGER NOT NULL DEFAULT 0
        CHECK (cfs_contribution >= 0)
);

CREATE TRIGGER trigger_grading_fired_rule_updated_at
    BEFORE UPDATE ON grading_fired_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grading_fired_rule IS
    'Individual frailty rules that evaluated to true during CFS grading.';
COMMENT ON COLUMN grading_fired_rule.rule_id IS
    'Identifier of the rule that fired (e.g. FA-001, CS-002, MF-003).';
COMMENT ON COLUMN grading_fired_rule.category IS
    'Category of the rule (e.g. Functional, Cognitive, Mobility, Nutrition, Polypharmacy).';
COMMENT ON COLUMN grading_fired_rule.description IS
    'Human-readable description of the rule.';
COMMENT ON COLUMN grading_fired_rule.cfs_contribution IS
    'Contribution of this rule to the CFS score.';

COMMENT ON COLUMN grading_fired_rule.grade_id IS
    'Foreign key to the grade table.';
COMMENT ON COLUMN grading_fired_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grading_fired_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN grading_fired_rule.updated_at IS
    'Timestamp when this row was updated.';
COMMENT ON COLUMN grading_fired_rule.deleted_at IS
    'Timestamp when this row was deleted.';

-- ========================================================================
-- END 91_create_table_grading_fired_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 92_create_table_grading_additional_flag.sql
-- ========================================================================

CREATE TABLE grading_additional_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    grade_id UUID NOT NULL
        REFERENCES grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(30) NOT NULL,
    category VARCHAR(100) NOT NULL DEFAULT '',
    message TEXT NOT NULL DEFAULT '',
    priority VARCHAR(10) NOT NULL DEFAULT 'medium'
        CHECK (priority IN ('high', 'medium', 'low'))
);

CREATE TRIGGER trigger_grading_additional_flag_updated_at
    BEFORE UPDATE ON grading_additional_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grading_additional_flag IS
    'Additional safety-critical flags detected during gerontology assessment grading (e.g. falls risk, delirium, safeguarding concern).';
COMMENT ON COLUMN grading_additional_flag.flag_id IS
    'Identifier of the flag (e.g. FLAG-FALL-001, FLAG-DELIR-001, FLAG-SAFEG-001).';
COMMENT ON COLUMN grading_additional_flag.category IS
    'Category of the flag (e.g. Falls Risk, Delirium, Malnutrition, Safeguarding).';
COMMENT ON COLUMN grading_additional_flag.message IS
    'Human-readable message describing the flagged concern.';
COMMENT ON COLUMN grading_additional_flag.priority IS
    'Priority level: high, medium, or low.';

COMMENT ON COLUMN grading_additional_flag.grade_id IS
    'Foreign key to the grade table.';
COMMENT ON COLUMN grading_additional_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grading_additional_flag.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN grading_additional_flag.updated_at IS
    'Timestamp when this row was updated.';
COMMENT ON COLUMN grading_additional_flag.deleted_at IS
    'Timestamp when this row was deleted.';

-- ========================================================================
-- END 92_create_table_grading_additional_flag.sql
-- ========================================================================

COMMENT ON COLUMN patient.deleted_at IS
    'Soft-delete timestamp; NULL when the row is live.';
